<script setup>
import { Head, Link, router } from '@inertiajs/vue3';
import { ref } from 'vue';

const props = defineProps({
    sucursal_seleccionada: { type: Object, required: true }, sucursales: { type: Array, default: () => [] }, filtros: { type: Object, required: true },
    resumen: { type: Object, required: true }, pagos_por_tipo: { type: Array, default: () => [] }, productos_vendidos: { type: Array, default: () => [] }, alertas_inventario: { type: Array, default: () => [] },
});
const fecha_inicio = ref(props.filtros.fecha_inicio);
const fecha_fin = ref(props.filtros.fecha_fin);
const consultar = () => router.get('/reportes', { ref_sucursal: props.sucursal_seleccionada.id_sucursal, fecha_inicio: fecha_inicio.value, fecha_fin: fecha_fin.value }, { preserveState: false, preserveScroll: true });
const cambiarSucursal = (evento) => router.get('/reportes', { ref_sucursal: evento.target.value, fecha_inicio: fecha_inicio.value, fecha_fin: fecha_fin.value }, { preserveState: false, preserveScroll: true });
const dinero = (valor) => `$${Number(valor || 0).toFixed(2)}`;
</script>

<template>
    <Head title="Reportes" />
    <main class="savix-pos-administracion"><header class="savix-pos-administracion__encabezado"><div class="savix-pos-marca"><span class="savix-pos-marca__sello">SI</span><div><p class="savix-pos-marca__nombre">Reportes</p><p class="savix-pos-marca__subtitulo">Ventas e inventario</p></div></div><Link class="savix-pos-boton savix-pos-boton--secundario" href="/panel">Volver al panel</Link></header><section class="savix-pos-administracion__contenido"><div class="savix-pos-seccion__titulo"><p class="savix-pos-eyebrow">INDICADORES</p><h1>Ventas e inventario</h1><p>Resumen de {{ sucursal_seleccionada.nombre }} para el periodo seleccionado.</p></div><div class="savix-pos-cuadricula savix-pos-cuadricula--tres"><label class="savix-pos-campo"><span>Sucursal</span><select :value="sucursal_seleccionada.id_sucursal" @change="cambiarSucursal"><option v-for="item in sucursales" :key="item.id_sucursal" :value="item.id_sucursal">{{ item.nombre }}</option></select></label><label class="savix-pos-campo"><span>Fecha inicial</span><input v-model="fecha_inicio" type="date"></label><label class="savix-pos-campo"><span>Fecha final</span><input v-model="fecha_fin" type="date"></label></div><button class="savix-pos-boton savix-pos-boton--primario" type="button" @click="consultar">Actualizar reporte</button>
        <section class="savix-pos-seccion"><div class="savix-pos-lista"><article class="savix-pos-lista__fila"><div><strong>Ventas cerradas</strong><span>Tickets liquidados en el periodo</span></div><strong>{{ resumen.ventas_cerradas }}</strong></article><article class="savix-pos-lista__fila"><div><strong>Venta total</strong><span>Pagos registrados</span></div><strong>{{ dinero(resumen.importe_ventas) }}</strong></article><article class="savix-pos-lista__fila"><div><strong>Ticket promedio</strong><span>Venta total entre tickets cerrados</span></div><strong>{{ dinero(resumen.ticket_promedio) }}</strong></article><article class="savix-pos-lista__fila"><div><strong>Compras registradas</strong><span>Entradas de inventario</span></div><strong>{{ dinero(resumen.importe_compras) }}</strong></article><article class="savix-pos-lista__fila"><div><strong>Alertas de inventario</strong><span>Recursos en o bajo el mínimo</span></div><strong :class="resumen.alertas_inventario ? 'savix-pos-error' : ''">{{ resumen.alertas_inventario }}</strong></article></div></section>
        <section class="savix-pos-seccion"><div class="savix-pos-seccion__subtitulo"><h2>Formas de pago</h2><p>Importe cobrado por cada método.</p></div><div class="savix-pos-lista"><article v-for="pago in pagos_por_tipo" :key="pago.tipo_pago" class="savix-pos-lista__fila"><strong>{{ pago.tipo_pago }}</strong><strong>{{ dinero(pago.importe) }}</strong></article><p v-if="!pagos_por_tipo.length" class="savix-pos-vacio">No hay pagos en este periodo.</p></div></section>
        <section class="savix-pos-seccion"><div class="savix-pos-seccion__subtitulo"><h2>Productos más vendidos</h2><p>Los 10 con mayor importe vendido.</p></div><div class="savix-pos-lista"><article v-for="producto in productos_vendidos" :key="producto.ref_producto" class="savix-pos-lista__fila"><div><strong>{{ producto.nombre_producto }}</strong><span>{{ Number(producto.cantidad_vendida).toFixed(3) }} unidades</span></div><strong>{{ dinero(producto.importe_vendido) }}</strong></article><p v-if="!productos_vendidos.length" class="savix-pos-vacio">No hay ventas cerradas en este periodo.</p></div></section>
        <section class="savix-pos-seccion"><div class="savix-pos-seccion__subtitulo"><h2>Inventario por atender</h2><p>Existencias que llegaron al mínimo configurado.</p></div><div class="savix-pos-lista"><article v-for="alerta in alertas_inventario" :key="`${alerta.tipo}-${alerta.nombre}`" class="savix-pos-lista__fila"><div><strong>{{ alerta.nombre }}</strong><span>{{ alerta.tipo }}</span></div><strong class="savix-pos-error">{{ alerta.existencia_actual }} / mínimo {{ alerta.existencia_minima }}</strong></article><p v-if="!alertas_inventario.length" class="savix-pos-vacio">No hay alertas de inventario.</p></div></section>
    </section></main>
</template>
